6	
7	use core::marker::PhantomData;
8	use core::sync::atomic::{AtomicU32, Ordering};
9	use zerocopy::{FromBytes, IntoBytes, KnownLayout};
10	
11	use super::{MOVED, Segments, TOMBSTONE, check_body_type, seq_of, word, word_pos, word_seg};
12	use crate::Full;
