211	/// The four lines at the front of every segment: the ring's
212	/// control block in segment 0, and the same layout in the others
213	/// so every segment's slots start at one offset.
214	///
215	/// - The pool buffer index of each segment is in the table, so a
216	///   process holding the pool and segment 0's index finds every
217	///   segment: the offsets-only rule, applied to the ring's table.
218	/// - The claims are their own line, so the CAS that takes a role
219	///   never shares a line with `given`.
220	#[repr(C)]
221	struct SegmentHeader {
222	    /// Line 0: the ring's identity and geometry, `given`, and the
223	    /// segment's resume positions.
224	    info: CacheAligned<Info>,
225	    /// Line 1: the role claims and checkpoints, segment 0's only.
226	    claims: CacheAligned<Claims>,
227	    /// Lines 2 and 3: the pool buffer index of segment `i` at
228	    /// `table[i]`, [`NO_SEGMENT`] past `seg_count`, segment 0's
229	    /// only.
230	    table: CacheAligned<[AtomicU32; MAX_SEGMENTS as usize]>,
231	}
232	
233	const _: () = assert!(size_of::<SegmentHeader>() == 4 * CACHE_LINE_SIZE);
234	
235	/// Bytes a segment needs: its header lines, then the slots.
236	///
237	/// - The pool handed to [`Ring::init`] needs buffers at least
238	///   this large.
239	/// - Computed in u64 for the same 32-bit wrap reason as the
240	///   rings' region sizes.
241	pub fn segment_size(slot_size: u32, seg_capacity: u32) -> u64 {
242	    size_of::<SegmentHeader>() as u64 + slot_size as u64 * seg_capacity as u64
243	}
