    /// The producer's switch in flight, `0` when none.
    prod_switch: AtomicU32,
    /// The consumer's segment.
    cons_cur: AtomicU32,
    /// The consumer's position in its segment, written by
    /// `release`.
    cons_pos: AtomicU32,
    /// The consumer's switch in flight, `0` when none.
    cons_switch: AtomicU32,
