                // sees the rest of the block.
                header.info.magic.store(MAGIC, Ordering::Release);
            }
        }
        Ok(Ring {
            segs: Segments::load(base, buf_size, &indices, slot_size, seg_capacity, seg_count),
            first_segment: indices[0],
            _region: core::marker::PhantomData,
