674	    fn positions_survive_the_wrap() {
675	        // Both sides two positions shy of the 26-bit wrap in every
676	        // segment, each segment's seqs claimable for the lap that
677	        // starts there, then several laps across it.
678	        let mut r = Region::new();
679	        let mut pool = Pool::init(&mut r.0, BUF as u32, BUFS as u32).unwrap();
680	        let ring = MpscRing::init(&mut pool, 64, 4, 3).unwrap();
681	        let start = SEQ_MASK - 1;
682	        for seg in 0..3 {
683	            for i in 0..4u32 {
684	                let idx = start.wrapping_add(i);
685	                ring.segs
686	                    .seq(seg, idx)
687	                    .store(seq_of(idx), Ordering::Relaxed);
688	            }
689	            // The next taker resumes where the seal says.
690	            ring.segs.seal(seg).store(start, Ordering::Relaxed);
691	        }
692	        ring.segs.claim().store(word(0, start), Ordering::Relaxed);
693	        let (prod, mut cons) = ring.split();
694	        cons.st.pos = start;
695	        cons.st.resume = [start; MAX_SEGMENTS as usize];
696	        // Batches of at most the ring's 12, so no send finds Full.
697	        for (from, to) in [(0u64, 12u64), (12, 24), (24, 30), (30, 41)] {
698	            send(&prod, from, to);
699	            recv(&mut cons, from, to);
700	            assert_eq!(free_segments(&prod).count_ones(), 2);
701	        }
702	        // The positions did cross the wrap.
703	        assert!(cons.st.pos < start);
704	        assert!(word_pos(prod.segs.claim().load(Ordering::Relaxed)) < start);
705	    }
