707	    #[test]
708	    fn a_stale_seal_does_not_end_a_reused_segment() {
709	        // Segment 0 is sealed, given back, and taken again: its
710	        // old seal must not end its second use at the old end
711	        // position.
712	        let mut r = Region::new();
713	        let mut pool = Pool::init(&mut r.0, BUF as u32, BUFS as u32).unwrap();
714	        let (prod, mut cons) = MpscRing::init(&mut pool, 64, 2, 2).unwrap().split();
715	        send(&prod, 0, 3);
716	        recv(&mut cons, 0, 3);
717	        assert_eq!(cons.segment(), 1);
718	        // Fill segment 1, switch back to 0, and run a whole lap of
719	        // 0 past its old end position of 2.
720	        send(&prod, 3, 6);
721	        assert_eq!(prod.segment(), 0);
722	        recv(&mut cons, 3, 6);
723	        assert_eq!(cons.segment(), 0);
724	        assert_eq!(cons.reserve_slot_with::<Msg>(|_| false).err(), Some(Empty));
725	        assert_eq!(cons.switches(), prod.switches());
726	    }
