    ///   pool and [`first_segment`](MpscRing::first_segment) can
    ///   find the ring.
    pub fn init(
        pool: &mut Pool<'a>,
        slot_size: u32,
        seg_capacity: u32,
        seg_count: u32,
    ) -> Result<Self, Error> {
