                    let msg = cons.reserve_slot_wait::<Msg>(|_| true).unwrap(); // OK: a policy of |_| true never gives up
                    let p = msg.val as usize;
                    assert_eq!(msg.seq, next[p], "per-producer order broken");
                    next[p] += 1;
